long long n, k,mod;
int jc[262155];
int inv[262155]; 
inline int ksm(int x, long long y) {
	int ret = 1;
	while(y) {
		if(y & 1) {
			ret = (long long)ret * x % mod;
		}
		x = (long long) x * x % mod;
		y >>= 1;
	}
	return ret;
}
int dp[262155][31];
bool vis[262155][31];
int Log[262155];
inline int getcnt(int x) {
	int cnt = 0;
	while(x && x % 2==0) {
		++cnt;
		x /= 2;
	}
	return cnt;
}
int jc2[262155];
inline int C(int n, int m) {
	return (long long)jc[n] * inv[m] % mod * inv[n - m] % mod;
} 
inline int dfs(int n, int k) {
	if(n == 0) return 1;
	if(k == 0) return 0;
	if(dp[n][k] != -1) {
		return dp[n][k];
	}
	int di = (1 << (Log[n])), ret = 0;
	for(register int i = n; i >= di; i -= 2) {
		ret = ((long long)ret + (((long long)C(n, i) * dfs(n - i, k - 1)) % mod) * k) % mod;
	}
	return dp[n][k] = ret;
}
vector<pair<int, int> >tp;
inline int bfs(int n, int k) {
	static queue<pair<int, int> > que;
	que.push(make_pair(n, k));
	while(!que.empty()) {
		n = que.front().first, k = que.front().second;
		que.pop();
		tp.push_back(make_pair(n, k));
		if(n == 0 || k == 0) continue;
		int di = (1 << (Log[n]));
		for(register int i = n; i >= di; i -= 2) {
			if(jc2[i] + jc2[n - i] == jc2[n] && !vis[n - i][k - 1]){
				vis[n - i][k - 1] = 1;
				que.push(make_pair(n - i, k - 1));
			} 
		}
	}
	for(int i = tp.size() - 1; i >= 0; --i) {
		n = tp[i].first, k = tp[i].second;
		if(n == 0) {
			dp[n][k] = 1; continue;
		}
		if(k == 0) {
			dp[n][k] = 0;continue;
		}
		int di = (1 << (Log[n]));
		for(register int i = n; i >= di; i -= 2) {
			if(jc2[i] + jc2[n - i] == jc2[n])
			dp[n][k] = ((long long)dp[n][k] + (((long long)C(n, i) * dp[n - i][k - 1]) % mod) * k) % mod; 
		}
	}
	return dp[n][k];
}
